"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { SFSymbol } from "@/components/icons/SFSymbol";
import { inputBoxVariants } from "@/components/ui/input";
import { masks, type MaskName } from "@/lib/masks";

// Generated by shadcn, restyled with the Lachmat tokens and trimmed to what the
// Figma uses: an input with a prefix ("#", "R$") and/or an action/message on the right.

// The gray box; the input inside it is transparent
const InputGroup = ({
  className,
  tone,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof inputBoxVariants>) => {
  return (
    <div
      data-slot="input-group"
      role="group"
      className={cn(
        inputBoxVariants({ tone }),
        "relative flex items-center has-[>[data-align=inline-start]]:[&>[data-slot=input-group-control]]:pl-2.5",
        className,
      )}
      {...props}
    />
  );
};

const inputGroupAddonVariants = cva(
  "flex h-full cursor-text items-center gap-2 select-none",
  {
    variants: {
      align: {
        "inline-start": "order-first pl-4 font-condensed",
        "inline-end": "order-last pr-4",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  },
);

// Clicking the addon (but not a button inside it) focuses the input
const InputGroupAddon = ({
  className,
  align = "inline-start",
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof inputGroupAddonVariants>) => {
  return (
    <div
      data-slot="input-group-addon"
      data-align={align}
      className={cn(inputGroupAddonVariants({ align }), className)}
      onClick={(e) => {
        if ((e.target as HTMLElement).closest("button")) {
          return;
        }
        e.currentTarget.parentElement?.querySelector("input")?.focus();
      }}
      {...props}
    />
  );
};

// Text action inside the field, e.g. "Calcular o frete", "Aplicar", "Gerar"
const InputGroupButton = ({
  className,
  type = "button",
  ...props
}: Omit<React.ComponentProps<typeof Button>, "variant" | "size">) => {
  return (
    <Button
      type={type}
      variant="ghost"
      size="sm"
      className={cn("text-[18px] text-current hover:text-current/60", className)}
      {...props}
    />
  );
};

// The input sits in a wrapper that holds the padding, so the mask template can be
// laid over it at exactly the same position. className goes to the wrapper
const InputGroupInput = ({
  className,
  mask,
  value,
  defaultValue,
  onChange,
  ...props
}: React.ComponentProps<"input"> & {
  // only digits, formatted: "cep", "sku", "card", "cvv", "expiry", "price"
  mask?: MaskName;
}) => {
  // what is typed, to know how much of the template is already filled
  const [typed, setTyped] = React.useState(String(value ?? defaultValue ?? ""));
  const shown = value !== undefined ? String(value) : typed;
  const template = mask && masks[mask].template;

  return (
    <div
      data-slot="input-group-control"
      className={cn("relative h-full min-w-0 flex-1 px-4", template && "tracking-[0.05em] tabular-nums", className)}
    >
      <input
        inputMode={mask ? "numeric" : undefined}
        className={cn(
          "peer size-full bg-transparent outline-none placeholder:text-current/40",
          // the template replaces the placeholder while focused
          template && "focus:placeholder:text-transparent placeholder:tracking-[-0.4px]",
        )}
        value={value}
        defaultValue={defaultValue}
        onChange={(e) => {
          if (mask) e.currentTarget.value = masks[mask].format(e.currentTarget.value);
          setTyped(e.currentTarget.value);
          onChange?.(e);
        }}
        {...props}
      />
      {template && (
        // "40110 - 9" + "__": an invisible copy of the typed text pushes the
        // rest of the template right after it, so each "_" is replaced in place
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 hidden items-center whitespace-pre [padding:inherit] peer-focus:flex"
        >
          <span className="invisible">{shown}</span>
          <span className="text-current/40">{template.slice(shown.length)}</span>
        </span>
      )}
    </div>
  );
};

// Red asterisk (SF Symbol) at a fixed distance to the right of the field. It is absolutely positioned,
// so it takes no space in the layout: the field keeps the full width of its container.
// Purely visual: mark the input itself with `required` for screen readers and validation
const InputGroupRequired = ({
  className,
  ...props
}: React.ComponentProps<"span">) => {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "absolute top-1/2 left-full ml-3 flex -translate-y-1/2 text-[11px] font-bold text-discount",
        className,
      )}
      {...props}
    >
      <SFSymbol name="asterisk" />
    </span>
  );
};

export {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupRequired,
};
